<script setup>
import { computed, onMounted, onUnmounted, ref } from 'vue';
import './styles/ui-tokens.css';import './styles/shell.css';
import WorkSessionView from './components/WorkSessionView.vue';import FuelForm from './components/FuelForm.vue';import AuthoritativeRecordForm from './components/AuthoritativeRecordForm.vue';import KfeDestinationView from './components/KfeDestinationView.vue';import KfeModuleView from './components/KfeModuleView.vue';import KfeFinancialModuleView from './components/KfeFinancialModuleView.vue';import KfeTimelineView from './components/KfeTimelineView.vue';import VehicleModuleView from './components/VehicleModuleView.vue';import DriverModuleView from './components/DriverModuleView.vue';import MaintenanceModuleView from './components/MaintenanceModuleView.vue';import ComplianceModuleView from './components/ComplianceModuleView.vue';import LoanModuleView from './components/LoanModuleView.vue';import PerformanceModuleView from './components/PerformanceModuleView.vue';import HistoricalEntriesView from './components/HistoricalEntriesView.vue';import AdminModuleView from './components/AdminModuleView.vue';
import { application } from '../js/app.js';import { createUiRouter } from '../js/ui/router.js';import { createUiState, UI_STATES } from '../js/ui/state.js';import { detectUiCapabilities } from '../js/ui/capabilities.js';import { createInteractionGuard } from '../js/ui/interaction.js';import { createUiLifecycle } from '../js/ui/lifecycle.js';import { enforceDecimalInput } from '../js/ui/decimal-input.js';import { prefersReducedMotion, watchReducedMotion } from '../js/ui/accessibility.js';import { installFormDraftRecovery } from '../js/ui/form-drafts.js';
const PRIMARY_DESTINATIONS=['Work','Performance','Timeline','Admin'];const TIMELINE_HORIZONS=['Day','Week','Long-term'];const FINANCIAL_MODULES=['Dashboard','Profitability'];
const online=ref(typeof navigator==='undefined'?true:navigator.onLine),activeModule=ref('Work'),uiState=ref(UI_STATES.IDLE),capabilities=ref(detectUiCapabilities()),storageState=ref('Ready'),syncState=ref(online.value?'Online':'Offline'),reducedMotion=ref(prefersReducedMotion()),timelineHorizon=ref('Day'),timelineEvents=ref([]),performanceModel=ref(null),fuelRecords=ref([]),fuelHistoryOpen=ref(false),globalFuelOpen=ref(false),historicalEditEvent=ref(null),workHeader=ref({shiftActive:false,startedAt:null,latestOdometer:null});
const router=createUiRouter({initialPath:activeModule.value,onChange:path=>{activeModule.value=path;}});const state=createUiState();const interaction=createInteractionGuard();const lifecycle=createUiLifecycle({onOnline:()=>{online.value=true;syncState.value='Online';},onOffline:()=>{online.value=false;syncState.value='Offline';}});let stopReducedMotionWatch=()=>{};let workHeaderTimer;
const currentDestination=computed(()=>PRIMARY_DESTINATIONS.includes(activeModule.value)?activeModule.value:'Work');function formatDuration(totalSeconds){const s=Math.max(0,Number(totalSeconds)||0);return [Math.floor(s/3600),Math.floor(s/60)%60,Math.floor(s)%60].map(v=>String(v).padStart(2,'0')).join(':');}const headerShiftSeconds=computed(()=>workHeader.value.startedAt?Math.max(0,Math.floor((Date.now()-Date.parse(workHeader.value.startedAt))/1000)):0);
function refresh(){online.value=typeof navigator==='undefined'?true:navigator.onLine;syncState.value=online.value?'Online':'Offline';capabilities.value=detectUiCapabilities();}async function loadWorkHeader(){try{const model=await application.getWorkScreenState();workHeader.value={shiftActive:model.shift.active,startedAt:model.shift.startedAt,latestOdometer:model.latestOdometer??null};}catch{workHeader.value={shiftActive:false,startedAt:null,latestOdometer:null};}}async function loadPerformance(){try{performanceModel.value=await application.getPerformance();}catch(error){performanceModel.value={error:String(error?.message||error)};}}async function loadTimeline(){try{const model=await application.getTimeline(timelineHorizon.value);timelineEvents.value=model.events||[];}catch{timelineEvents.value=[];}}async function loadFuel(){try{fuelRecords.value=await application.listFuel();}catch{fuelRecords.value=[];}}
async function navigate(path){const result=await interaction.run(async()=>router.navigate(path));if(!result.accepted)return;state.set(UI_STATES.READY);uiState.value=state.state;interaction.reset();if(path==='Performance')await loadPerformance();if(path==='Timeline')await loadTimeline();if(path==='Fuel')await loadFuel();if(path==='Work')await loadWorkHeader();}async function changeTimelineHorizon(horizon){timelineHorizon.value=horizon;await loadTimeline();}function openModuleAction(action){if(typeof action==='string'){void navigate(action);return;}if(action?.module==='Fuel'&&action?.action==='Fuel history'){fuelHistoryOpen.value=true;void loadFuel();}}
async function handleSaveRequest(payload){try{const module=payload?.module;const value=payload?.value||{};if(module==='Expenses')await application.recordExpense(value);else if(module==='Revenue')await application.recordRevenue({amount_paise:Math.round(Number(value.amount)*100),business_date:value.date,recorded_at:new Date().toISOString(),scope:'BUSINESS'});else if(module==='Maintenance')await application.recordMaintenance(value);else if(module==='Compliance')await application.recordCompliance(value);else{openModuleAction(payload);return;}await loadPerformance();}catch(error){performanceModel.value={error:String(error?.message||error)};}}
function handleCalculationRequest(payload){openModuleAction(payload);}async function handleFuelUndo(id){try{await application.undoFuel(id);await loadFuel();await loadPerformance();}catch(error){performanceModel.value={error:String(error?.message||error)};}}async function handleHistoricalSave(payload){try{if(payload.kind==='HISTORICAL_DAY')await application.recordHistoricalDay(payload.value);else if(payload.kind==='HISTORICAL_FUEL')await application.recordHistoricalFuel(payload.value);else throw new Error('Unknown historical entry');payload.done?.(true,payload.kind==='HISTORICAL_DAY'?'Historical day saved safely.':'Historical fuel entry saved safely.');await loadPerformance();}catch(error){payload.done?.(false,String(error?.message||error));}}function handleTimelineEdit(event){historicalEditEvent.value=event;}async function handleAuthoritativeSaved(){await Promise.all([loadTimeline(),loadPerformance(),loadFuel(),loadWorkHeader()]);}function handleFuelSaved(){globalFuelOpen.value=false;void Promise.all([loadTimeline(),loadPerformance(),loadFuel(),loadWorkHeader()]);}function handleGlobalFuelClose(){globalFuelOpen.value=false;void Promise.all([loadPerformance(),loadFuel(),loadWorkHeader()]);}async function handleResetRequest(){try{await application.resetAllData();window.location.reload();}catch(error){performanceModel.value={error:String(error?.message||error)};}}
function enforceDecimalInputs(event){const target=event.target;if(!(target instanceof HTMLInputElement))return;const isNumeric=target.type==='number'||target.inputMode==='decimal';if(!isNumeric)return;const scale=Number.parseInt(target.dataset.kfeDecimalScale||'2',10);const value=enforceDecimalInput(target,{scale:Number.isFinite(scale)?scale:2,allowNegative:target.dataset.kfeAllowNegative==='true'});if(target.value!==value)target.value=value;}function handleBack(){router.handleBack();}function handleWorkStateChanged(){void loadWorkHeader();void loadPerformance();}function openGlobalFuel(){if(activeModule.value==='Work')globalFuelOpen.value=true;}
onMounted(()=>{router.start();lifecycle.start();installFormDraftRecovery();stopReducedMotionWatch=watchReducedMotion(value=>{reducedMotion.value=value;});refresh();void loadPerformance();void loadTimeline();void loadWorkHeader();window.addEventListener('kfe:work-state-changed',handleWorkStateChanged);workHeaderTimer=setInterval(()=>{workHeader.value={...workHeader.value};},1000);state.set(UI_STATES.READY);uiState.value=state.state;});onUnmounted(()=>{router.stop();lifecycle.stop();stopReducedMotionWatch();window.removeEventListener('kfe:work-state-changed',handleWorkStateChanged);clearInterval(workHeaderTimer);});window.KFE_VUE_RUNTIME={online,activeModule,uiState,capabilities,reducedMotion,handleBack};
</script>
<template><div class="kfe-shell" data-framework="vue" @input.capture="enforceDecimalInputs"><header class="kfe-topbar" aria-label="KFE application header"><div class="kfe-brand"><strong>KFE 2.0</strong><span>Kanishka Fleet ERP</span></div><div v-if="workHeader.shiftActive" class="kfe-global-shift-timer" aria-label="Active shift timer"><span>SHIFT</span>{{formatDuration(headerShiftSeconds)}}</div><div class="kfe-status" aria-label="Application status"><span class="kfe-status-dot" aria-hidden="true"></span><span>{{syncState}} · {{storageState}}</span></div></header><main class="kfe-viewport" aria-label="Main application viewport"><section class="kfe-workspace" aria-live="polite"><WorkSessionView v-if="activeModule==='Work'"/><PerformanceModuleView v-else-if="activeModule==='Performance'" :online="online" :performance="performanceModel"/><KfeDestinationView v-else-if="activeModule==='Timeline'" title="Timeline" subtitle="Authoritative events, ordered by their recorded occurrence time."><div class="kfe-segmented" aria-label="Timeline horizon"><button v-for="horizon in TIMELINE_HORIZONS" :key="horizon" type="button" :class="{'is-active':timelineHorizon===horizon}" @click="changeTimelineHorizon(horizon)">{{horizon}}</button></div><KfeTimelineView :horizon="timelineHorizon" :events="timelineEvents" @edit="handleTimelineEdit"/></KfeDestinationView><AdminModuleView v-else-if="activeModule==='Admin'" :application="application" :online="online" @open="openModuleAction"/><HistoricalEntriesView v-else-if="activeModule==='Historical Entries'" @back="navigate('Admin')" @save-request="handleHistoricalSave"/><VehicleModuleView v-else-if="activeModule==='Vehicle'" :application="application" @back="navigate('Admin')" @open="openModuleAction"/><DriverModuleView v-else-if="activeModule==='Driver'" :application="application" @back="navigate('Vehicle')"/><MaintenanceModuleView v-else-if="activeModule==='Maintenance'" :application="application" @save-request="handleSaveRequest"/><ComplianceModuleView v-else-if="activeModule==='Compliance'" :application="application" @save-request="handleSaveRequest" @back="navigate('Admin')"/><LoanModuleView v-else-if="activeModule==='Loans'" :application="application" @save-request="handleSaveRequest" @calculation-request="handleCalculationRequest" @open="openModuleAction" @back="navigate('Admin')"/><KfeFinancialModuleView v-else-if="FINANCIAL_MODULES.includes(activeModule)" :module="activeModule" @open="openModuleAction" @back="navigate('Admin')"/><KfeModuleView v-else :key="activeModule" :module="activeModule" :application="application" @open="openModuleAction" @back="navigate('Admin')" @reset-request="handleResetRequest" @save-request="handleSaveRequest"/></section></main><div v-if="activeModule==='Work'" class="kfe-global-fuel-action"><button type="button" aria-label="Quick fuel" @click="openGlobalFuel">⛽ FUEL</button></div><FuelForm v-if="globalFuelOpen" mode="CREATE" :authoritative-odometer="workHeader.latestOdometer" @close="handleGlobalFuelClose" @saved="handleFuelSaved"/><FuelForm v-if="historicalEditEvent && historicalEditEvent.entityType==='Fuel'" mode="EDIT" :record="historicalEditEvent" @saved="handleAuthoritativeSaved" @close="closeAuthoritativeForm"/><AuthoritativeRecordForm v-else-if="historicalEditEvent" :type="historicalEditEvent.entityType==='Work Session'?'WORK_SESSION':historicalEditEvent.entityType==='Business Trip'?'BUSINESS_TRIP':historicalEditEvent.entityType==='Personal Trip'?'PERSONAL_TRIP':historicalEditEvent.entityType==='Revenue'?'REVENUE':historicalEditEvent.entityType==='Expense'?'EXPENSE':''" mode="EDIT" :record="historicalEditEvent" @saved="handleAuthoritativeSaved" @close="closeAuthoritativeForm"/><nav class="kfe-bottom-nav" aria-label="Primary driver navigation"><button v-for="destination in PRIMARY_DESTINATIONS" :key="destination" class="kfe-nav-item" type="button" :aria-current="currentDestination===destination?'page':undefined" @click="navigate(destination)">{{destination}}</button></nav></div></template>
<style>.kfe-global-fuel-action{position:fixed;right:14px;top:calc(14px + env(safe-area-inset-top));z-index:1050}.kfe-global-fuel-action button{border:0;border-radius:999px;padding:12px 16px;font-weight:800;box-shadow:0 8px 24px rgba(0,0,0,.18);background:var(--kfe-ui-surface);color:var(--kfe-ui-text);border:1px solid var(--kfe-ui-border)}.kfe-work-session .fuel-tab-wrap{display:none}</style>
